package com.loja.checkout.dominio;

import java.math.BigDecimal;

/**
 * Item de pedido já validado (preço, quantidade e peso presentes e positivos).
 */
public record ItemPedido(String nome, BigDecimal precoUnitario, int quantidade, BigDecimal pesoKg) {

    public BigDecimal subtotal() {
        return precoUnitario.multiply(BigDecimal.valueOf(quantidade));
    }

    public BigDecimal pesoTotal() {
        return pesoKg.multiply(BigDecimal.valueOf(quantidade));
    }
}

package com.loja.checkout.erro;

public class CheckoutException extends RuntimeException {

    private final CodigoErro codigo;

    public CheckoutException(CodigoErro codigo) {
        super(codigo.name());
        this.codigo = codigo;
    }

    public CodigoErro getCodigo() {
        return codigo;
    }
}

package com.loja.checkout.erro;

public record ErroResponse(String erro) {
}

package com.loja.checkout.erro;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(CheckoutException.class)
    public ResponseEntity<ErroResponse> tratarCheckoutException(CheckoutException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ErroResponse(ex.getCodigo().name()));
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ErroResponse> tratarJsonInvalido(HttpMessageNotReadableException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErroResponse(CodigoErro.PEDIDO_INVALIDO.name()));
    }
}

package com.loja.checkout.util;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Arredondamento monetário único usado em todas as etapas que produzem um valor em dinheiro:
 * "half to even" (banker's rounding), 2 casas decimais.
 */
public final class Arredondamento {

    private Arredondamento() {
    }

    public static BigDecimal monetario(BigDecimal valor) {
        return valor.setScale(2, RoundingMode.HALF_EVEN);
    }
}

package com.loja.checkout.api;

import java.math.BigDecimal;

/**
 * Representação crua de um item do carrinho tal como recebido no JSON.
 * Os campos são deliberadamente "nullable" (tipos boxed) para permitir detectar ausência
 * de valor na validação, antes de converter para o domínio.
 */
public class ItemRequest {

    private String nome;
    private BigDecimal precoUnitario;
    private Integer quantidade;
    private BigDecimal pesoKg;

    public ItemRequest() {
    }

    public String getNome() {
        return nome;
    }

    public void setNome(String nome) {
        this.nome = nome;
    }

    public BigDecimal getPrecoUnitario() {
        return precoUnitario;
    }

    public void setPrecoUnitario(BigDecimal precoUnitario) {
        this.precoUnitario = precoUnitario;
    }

    public Integer getQuantidade() {
        return quantidade;
    }

    public void setQuantidade(Integer quantidade) {
        this.quantidade = quantidade;
    }

    public BigDecimal getPesoKg() {
        return pesoKg;
    }

    public void setPesoKg(BigDecimal pesoKg) {
        this.pesoKg = pesoKg;
    }
}

package com.loja.checkout.api;

import java.util.List;

/**
 * Corpo cru da requisição. Os campos que representam "escolha entre casos" (modalidade,
 * cupom, forma de pagamento, nível de clube, região) são recebidos como String para que
 * um valor desconhecido vire um erro de negócio (ex.: MODALIDADE_INVALIDA) em vez de um
 * erro de desserialização do Jackson.
 */
public class CheckoutRequest {

    private List<ItemRequest> itens;
    private String modalidadeEntrega;
    private String cupom;
    private String formaPagamento;
    private Integer parcelas;
    private String nivelClube;
    private String regiao;

    public CheckoutRequest() {
    }

    public List<ItemRequest> getItens() {
        return itens;
    }

    public void setItens(List<ItemRequest> itens) {
        this.itens = itens;
    }

    public String getModalidadeEntrega() {
        return modalidadeEntrega;
    }

    public void setModalidadeEntrega(String modalidadeEntrega) {
        this.modalidadeEntrega = modalidadeEntrega;
    }

    public String getCupom() {
        return cupom;
    }

    public void setCupom(String cupom) {
        this.cupom = cupom;
    }

    public String getFormaPagamento() {
        return formaPagamento;
    }

    public void setFormaPagamento(String formaPagamento) {
        this.formaPagamento = formaPagamento;
    }

    public Integer getParcelas() {
        return parcelas;
    }

    public void setParcelas(Integer parcelas) {
        this.parcelas = parcelas;
    }

    public String getNivelClube() {
        return nivelClube;
    }

    public void setNivelClube(String nivelClube) {
        this.nivelClube = nivelClube;
    }

    public String getRegiao() {
        return regiao;
    }

    public void setRegiao(String regiao) {
        this.regiao = regiao;
    }
}

